-- Application EN LIGNE de S3 : données de l'entretien de cadrage (questions de terrain, temps, dimensions et questions), projet redtuedpnhbqziqmyyjc.
-- GÉNÉRÉ par scripts/generer-sql-profil-entretien.mjs le 2026-11-27 à partir des migrations locales et des fichiers de données.
-- NE PAS EXÉCUTER sans le feu vert explicite de Remyaga. Lire d'abord supabase/en-ligne/PROCEDURE-PROFIL-ENTRETIEN.md.
-- NE PAS utiliser `supabase db push` (la base en ligne n'a pas d'historique de migrations).
-- Exécution : npx supabase db query --remote=redtuedpnhbqziqmyyjc --file supabase/en-ligne/20261127_ref_entretien_donnees.sql
-- Une seule transaction : en cas d'erreur, rien n'est appliqué.
-- Prérequis : le schéma de S3 est en place (20261127_ref_entretien_cadrage.sql) ; les questions de terrain sont incluses ici car l'entretien les référence.
-- Rejouable : upsert, et une ligne déjà relue (statut autre que brouillon_ia) n'est jamais écrasée.
BEGIN;

-- Questions de terrain (mêmes lignes que npm run referentiel:importer en local).
ON CONFLICT (cle) DO UPDATE SET
  libelle = EXCLUDED.libelle,
  sous_titre = EXCLUDED.sous_titre,
  reponses = EXCLUDED.reponses,
  secteurs = EXCLUDED.secteurs,
  ordre = EXCLUDED.ordre,
  source = EXCLUDED.source
WHERE ref.questions_terrain.statut = 'brouillon_ia';

-- Les six temps de la consultation.
ON CONFLICT (cle) DO UPDATE SET
  ordre = EXCLUDED.ordre,
  titre = EXCLUDED.titre,
  intro = EXCLUDED.intro,
  source = EXCLUDED.source
WHERE ref.entretien_temps.statut = 'brouillon_ia';

-- Les sept dimensions de faisabilité et leurs règles de lecture.
ON CONFLICT (cle) DO UPDATE SET
  ordre = EXCLUDED.ordre,
  libelle = EXCLUDED.libelle,
  phrase_sans_alerte = EXCLUDED.phrase_sans_alerte,
  regles = EXCLUDED.regles,
  source = EXCLUDED.source
WHERE ref.entretien_dimensions.statut = 'brouillon_ia';

-- Les questions.
ON CONFLICT (cle) DO UPDATE SET
  temps = EXCLUDED.temps,
  ordre = EXCLUDED.ordre,
  question_terrain = EXCLUDED.question_terrain,
  libelle = EXCLUDED.libelle,
  aide = EXCLUDED.aide,
  type = EXCLUDED.type,
  unite = EXCLUDED.unite,
  reponses = EXCLUDED.reponses,
  remplit = EXCLUDED.remplit,
  condition = EXCLUDED.condition,
  dimension = EXCLUDED.dimension,
  essentielle = EXCLUDED.essentielle,
  court = EXCLUDED.court,
  source = EXCLUDED.source
WHERE ref.entretien_questions.statut = 'brouillon_ia';

COMMIT;
