INSERT INTO ref.questions_terrain (cle, libelle, sous_titre, reponses, secteurs, ordre, statut, source)
VALUES
('ecosysteme', 'Dans quel milieu se trouve ton exploitation ?', 'Le milieu oriente le choix des cultures et le risque d''inondation ou de sécheresse.', '[{"valeur":"plaine","libelle":"Plaine"},{"valeur":"bas_fond","libelle":"Bas-fond"},{"valeur":"plateau","libelle":"Plateau ou colline"},{"valeur":"periurbain","libelle":"Zone périurbaine"}]'::jsonb, ARRAY[]::text[], 1, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('accessibilite', 'Peut-on rejoindre ton site toute l''année ?', 'Un site isolé renchérit le transport des intrants et des récoltes.', '[{"valeur":"bonne","libelle":"Oui, route praticable toute l''année"},{"valeur":"saisonniere","libelle":"Difficile en saison des pluies"},{"valeur":"isolee","libelle":"Zone isolée"}]'::jsonb, ARRAY[]::text[], 2, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('saisonnalite', 'À quelle période produis-tu ?', 'La contre-saison paie mieux mais coûte plus en eau et en énergie.', '[{"valeur":"saison_pluies","libelle":"En saison des pluies"},{"valeur":"contre_saison","libelle":"En contre-saison (saison sèche)"},{"valeur":"toute_annee","libelle":"Toute l''année"}]'::jsonb, ARRAY['vegetal']::text[], 3, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('eau', 'D''où vient ton eau ?', 'Une motopompe ajoute du carburant à ton budget.', '[{"valeur":"pluie","libelle":"Pluie seulement"},{"valeur":"puits","libelle":"Puits"},{"valeur":"forage","libelle":"Forage"},{"valeur":"motopompe","libelle":"Rivière ou retenue avec motopompe"},{"valeur":"reseau","libelle":"Réseau d''eau"}]'::jsonb, ARRAY[]::text[], 4, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('mecanisation', 'Comment prépares-tu le sol ?', 'Le travail du sol pèse sur la main-d''œuvre et le calendrier.', '[{"valeur":"manuelle","libelle":"À la main"},{"valeur":"traction_animale","libelle":"Traction animale"},{"valeur":"tracteur_loue","libelle":"Tracteur loué"},{"valeur":"tracteur_propre","libelle":"Mon propre tracteur"}]'::jsonb, ARRAY['vegetal']::text[], 5, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('objectif', 'Quel est ton objectif principal ?', 'Il fixe la taille utile et le circuit de vente.', '[{"valeur":"complement_revenu","libelle":"Un complément de revenu"},{"valeur":"activite_principale","libelle":"Mon activité principale"},{"valeur":"contrat","libelle":"Livrer un acheteur sous contrat"}]'::jsonb, ARRAY[]::text[], 6, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('souche', 'Quelle souche ou race comptes-tu élever ?', 'Une souche améliorée produit plus mais demande plus de soins.', '[{"valeur":"locale","libelle":"Locale"},{"valeur":"amelioree","libelle":"Améliorée"},{"valeur":"importee","libelle":"Importée"}]'::jsonb, ARRAY['animal', 'halieutique']::text[], 7, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('logement', 'Comment seront logés tes animaux ?', 'Le logement protège des maladies et des vols.', '[{"valeur":"plein_air","libelle":"En plein air"},{"valeur":"semi_ouvert","libelle":"Abri semi-ouvert"},{"valeur":"batiment","libelle":"Bâtiment fermé"},{"valeur":"etang","libelle":"Étang en terre"},{"valeur":"bac","libelle":"Bacs ou cages"}]'::jsonb, ARRAY['animal', 'halieutique']::text[], 8, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('alimentation', 'Comment nourris-tu tes animaux ?', 'L''aliment industriel complet coûte plus cher mais fait grossir plus vite.', '[{"valeur":"paturage","libelle":"Pâturage"},{"valeur":"artisanal","libelle":"Aliment fabriqué sur place"},{"valeur":"industriel","libelle":"Aliment industriel complet"},{"valeur":"mixte","libelle":"Un mélange"}]'::jsonb, ARRAY['animal', 'halieutique']::text[], 9, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('energie', 'Quelle énergie utilises-tu ?', 'L''énergie compte pour l''éclairage, le froid et les machines.', '[{"valeur":"aucune","libelle":"Aucune"},{"valeur":"reseau","libelle":"Réseau électrique"},{"valeur":"groupe","libelle":"Groupe électrogène"},{"valeur":"solaire","libelle":"Solaire"}]'::jsonb, ARRAY[]::text[], 10, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('equipement', 'As-tu déjà le matériel nécessaire ?', 'Le matériel déjà acquis réduit ton investissement de départ.', '[{"valeur":"existant","libelle":"Oui, je l''ai"},{"valeur":"location","libelle":"Je vais le louer"},{"valeur":"a_acheter","libelle":"Je dois l''acheter"}]'::jsonb, ARRAY[]::text[], 11, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('approvisionnement', 'Où achètes-tu tes intrants ?', 'La distance au fournisseur pèse sur le prix rendu.', '[{"valeur":"proche","libelle":"Sur place ou tout près"},{"valeur":"ville_voisine","libelle":"Dans la ville voisine"},{"valeur":"lome","libelle":"À Lomé"}]'::jsonb, ARRAY[]::text[], 12, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('hygiene', 'Quelles règles d''hygiène appliques-tu ?', 'La biosécurité réduit fortement la mortalité.', '[{"valeur":"aucune","libelle":"Aucune règle particulière"},{"valeur":"de_base","libelle":"Nettoyage et désinfection de base"},{"valeur":"stricte","libelle":"Protocole strict (pédiluve, accès contrôlé)"}]'::jsonb, ARRAY['animal', 'halieutique', 'transformation']::text[], 13, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('stockage', 'Peux-tu stocker ta production ?', 'Stocker permet de vendre quand les prix remontent.', '[{"valeur":"aucun","libelle":"Non, je vends tout de suite"},{"valeur":"magasin","libelle":"Magasin ou grenier"},{"valeur":"froid","libelle":"Chambre froide"}]'::jsonb, ARRAY[]::text[], 14, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('canal_vente', 'À qui vas-tu vendre ?', 'Le circuit de vente change le prix que tu touches.', '[{"valeur":"bord_champ","libelle":"Bord champ"},{"valeur":"marche_local","libelle":"Marché local"},{"valeur":"grossiste","libelle":"Grossiste"},{"valeur":"restaurants","libelle":"Restaurants et hôtels"},{"valeur":"supermarche","libelle":"Supermarchés"},{"valeur":"export","libelle":"Export"}]'::jsonb, ARRAY[]::text[], 15, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.'),
('conditionnement', 'Comment présentes-tu ton produit ?', 'Un emballage soigné coûte un peu et se vend plus cher.', '[{"valeur":"vrac","libelle":"En vrac"},{"valeur":"standard","libelle":"Emballage simple"},{"valeur":"premium","libelle":"Emballage premium et étiquette"}]'::jsonb, ARRAY[]::text[], 16, 'brouillon_ia', 'Cultiso Brouillon, creer_simulation.php (16 clés) ; libellés et réponses rédigés par Cultiso, à valider.')
INSERT INTO ref.entretien_temps (cle, ordre, titre, intro, statut, source)
VALUES
('idee', 1, 'Ton idée et toi', 'On commence par comprendre ce que tu as en tête et qui tu es. Il n''y a pas de mauvaise réponse.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('existant', 2, 'Ce que tu as déjà', 'On fait le point sur ce que tu possèdes déjà : terre, eau, argent, temps, matériel. Ce que tu ne sais pas, on le laisse de côté pour l''instant.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('menage', 3, 'Ton ménage', 'Ton projet doit aussi faire vivre ta famille. On a besoin de savoir combien vous êtes et ce que vous dépensez.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('marche', 4, 'Le marché', 'Produire ne suffit pas : il faut vendre. On regarde si quelqu''un est prêt à t''acheter.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('contraintes', 5, 'Les contraintes et les risques', 'Chaque lieu a ses difficultés. Les connaître tôt évite les mauvaises surprises.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('retour', 6, 'Le point avec toi', 'On te redit ce qu''on a compris, ce qui est solide, ce qui inquiète et ce qu''il reste à éclaircir.', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.')
INSERT INTO ref.entretien_dimensions (cle, ordre, libelle, phrase_sans_alerte, regles, statut, source)
VALUES
('terre', 1, 'La terre', 'Tu disposes d''une terre et rien n''est bloquant pour l''instant.', '[{"si":{"champ":"terreStatut","op":"egal","valeur":"aucun"},"feu":"rouge","phrase":"Tu n''as pas encore de terre. Sans terre, pas de culture ni d''élevage : il faut d''abord en trouver une."},{"si":{"champ":"terreStatut","op":"dans","valeurs":["pret","metayage","concession_communautaire"]},"feu":"orange","phrase":"La terre ne t''appartient pas. Mets par écrit ce que tu peux en faire et pour combien de temps."},{"si":{"champ":"terrePente","op":"egal","valeur":"forte"},"feu":"orange","phrase":"La pente est forte : l''eau emporte la terre et le travail est plus dur. Il faudra prévoir des protections."},{"si":{"tous":[{"champ":"terreStatut","op":"dans","valeurs":["propriete","heritage_familial","location"]},{"champ":"terreSurfaceHa","op":"superieur","valeur":0}]},"feu":"vert","phrase":"Tu disposes de la terre."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('eau', 2, 'L''eau', 'Ton accès à l''eau ne pose pas de problème pour l''instant.', '[{"si":{"champ":"eauSource","op":"egal","valeur":"aucune"},"feu":"rouge","phrase":"Tu n''as pas d''eau. Sans eau, rien ne pousse ni ne grandit : il faut une source avant de te lancer."},{"si":{"champ":"eauSource","op":"egal","valeur":"pluie"},"feu":"orange","phrase":"Tu dépends de la pluie : tes récoltes suivront la saison des pluies et son irrégularité."},{"si":{"champ":"eauSaison","op":"dans","valeurs":["saison_pluies","irreguliere"]},"feu":"orange","phrase":"Ton eau n''est pas disponible toute l''année : le calendrier de production devra s''y adapter."},{"si":{"tous":[{"champ":"eauSource","op":"dans","valeurs":["puits","forage","reseau","cours_eau","retenue"]},{"champ":"eauSaison","op":"egal","valeur":"toute_annee"}]},"feu":"vert","phrase":"Tu as de l''eau toute l''année."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('travail', 3, 'Le travail', 'Tu as le temps et les bras pour démarrer.', '[{"si":{"champ":"tempsHeuresSemaine","op":"inferieur","valeur":5},"feu":"rouge","phrase":"Moins de 5 heures par semaine, c''est très peu pour conduire une production, même petite. Seuil de prudence, à confirmer avec un technicien."},{"si":{"champ":"tempsEngagement","op":"egal","valeur":"partiel"},"feu":"orange","phrase":"Tu fais autre chose à côté : il faut choisir une production qui te laisse du temps libre."},{"si":{"champ":"familleActifs","op":"egal","valeur":0},"feu":"orange","phrase":"Personne dans ta famille ne peut t''aider : la main d''œuvre sera à payer."},{"si":{"champ":"tempsEngagement","op":"egal","valeur":"plein"},"feu":"vert","phrase":"Tu peux t''y consacrer à plein temps."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('argent', 4, 'L''argent', 'Ta situation d''argent ne montre rien de bloquant pour l''instant. Les calculs viendront ensuite, avec les moteurs.', '[{"si":{"champ":"apportEspecesFcfa","op":"egal","valeur":0},"feu":"orange","phrase":"Tu ne peux pas mettre d''argent au départ. Un financeur regarde ce que tu apportes toi-même : on vérifiera sa règle plus tard."},{"si":{"champ":"nb_credits","op":"superieur","valeur":0},"feu":"orange","phrase":"Tu as déjà des crédits en cours. Leurs mensualités pèsent sur ton revenu : on les comptera dans le plan."},{"si":{"tous":[{"champ":"apportEspecesFcfa","op":"superieur","valeur":0},{"champ":"nb_credits","op":"egal","valeur":0}]},"feu":"vert","phrase":"Tu as de quoi mettre au départ et aucun crédit en cours."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('marche', 5, 'Le marché', 'Ton marché est identifié et rien n''est bloquant pour l''instant.', '[{"si":{"champ":"ctx.marche_acheteur","op":"dans","valeurs":["cherche","non"]},"feu":"orange","phrase":"Tu n''as pas encore d''acheteur. C''est le premier risque d''un projet agricole : trouve au moins un client avant de produire en grand."},{"si":{"tous":[{"champ":"ctx.marche_acheteur","op":"egal","valeur":"oui_identifie"},{"champ":"ctx.marche_contrat","op":"egal","valeur":"aucun"},{"champ":"ctx.marche_promesse","op":"egal","valeur":"aucune"}]},"feu":"orange","phrase":"Tu as un acheteur mais aucun engagement de sa part. Demande-lui une promesse d''achat écrite."},{"si":{"tous":[{"champ":"ctx.marche_acheteur","op":"egal","valeur":"oui_identifie"},{"champ":"ctx.marche_promesse","op":"egal","valeur":"orale"},{"champ":"ctx.marche_contrat","op":"pas_dans","valeurs":["contrat_ecrit"]}]},"feu":"orange","phrase":"Ton acheteur a promis à l''oral. C''est un début, mais cela ne te protège pas : essaie de le mettre par écrit."},{"si":{"tous":[{"champ":"ctx.marche_acheteur","op":"egal","valeur":"oui_identifie"},{"un_des":[{"champ":"ctx.marche_contrat","op":"egal","valeur":"contrat_ecrit"},{"champ":"ctx.marche_promesse","op":"egal","valeur":"ecrite"}]}]},"feu":"vert","phrase":"Ton acheteur s''est engagé par écrit : c''est solide."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('savoir_faire', 6, 'Le savoir-faire', 'Tu connais le métier et rien n''est bloquant pour l''instant.', '[{"si":{"champ":"competenceTechnique","op":"dans","valeurs":["aucune","debutant"]},"feu":"orange","phrase":"Tu débutes dans ce métier. Fais-toi accompagner par un technicien ou un producteur expérimenté, et commence petit."},{"si":{"champ":"competenceGestion","op":"egal","valeur":"aucune"},"feu":"orange","phrase":"Tu n''as pas l''habitude de tenir des comptes. Cultiso t''aidera à suivre ce que tu dépenses et ce que tu gagnes."},{"si":{"champ":"competenceVente","op":"egal","valeur":"aucune"},"feu":"orange","phrase":"Tu n''as jamais vendu de produits. Prépare ta vente avant la récolte."},{"si":{"champ":"competenceTechnique","op":"dans","valeurs":["moyen","solide"]},"feu":"vert","phrase":"Tu connais déjà le métier."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('regles', 7, 'Les règles et papiers', 'Tes papiers ne bloquent rien pour l''instant. Les règles précises du financeur visé seront contrôlées ensuite.', '[{"si":{"champ":"terrePiece","op":"dans","valeurs":["accord_verbal","aucune"]},"feu":"orange","phrase":"Tu n''as aucune pièce écrite sur la terre. Un financeur voudra savoir que tu peux l''utiliser pendant toute la durée du projet : une pièce écrite aide."},{"si":{"champ":"terreDureeAnnees","op":"inferieur","valeur":3},"feu":"orange","phrase":"Ton droit d''utiliser la terre est court (moins de 3 ans). C''est risqué si tu investis. Seuil de prudence, à confirmer avec le financeur visé."},{"si":{"champ":"terrePiece","op":"dans","valeurs":["titre_foncier","attestation_villageoise","contrat_ecrit"]},"feu":"vert","phrase":"Tu as une pièce écrite sur la terre. C''est un bon point pour un dossier, à confirmer avec le financeur visé."}]'::jsonb, 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.')
INSERT INTO ref.entretien_questions (cle, temps, ordre, question_terrain, libelle, aide, type, unite, reponses, remplit, condition, dimension, essentielle, court, statut, source)
VALUES
('idee', 'idee', 1, NULL, 'Dis-moi en quelques mots ce que tu veux produire ou vendre.', 'Par exemple : des tomates, des poulets de chair, du poisson. Pas besoin de chiffres.', 'texte', NULL, NULL, '{"cible":"contexte","champ":"idee"}'::jsonb, NULL, NULL, true, 'ton idée', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('avancement', 'idee', 2, NULL, 'Où en es-tu de ton projet ?', NULL, 'choix', NULL, '[{"valeur":"idee","libelle":"Ce n''est encore qu''une idée"},{"valeur":"reflexion","libelle":"Je réfléchis, je me renseigne"},{"valeur":"preparation","libelle":"Je prépare (terre, matériel, contacts)"},{"valeur":"demarre","libelle":"J''ai déjà démarré"},{"valeur":"en_production","libelle":"Je produis déjà et je veux grandir"}]'::jsonb, '{"cible":"profil","champ":"avancement"}'::jsonb, NULL, NULL, true, 'où tu en es', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('finalites', 'idee', 3, NULL, 'Qu''est-ce que tu attends de ce projet ?', 'Tu peux choisir plusieurs réponses.', 'choix_multiple', NULL, '[{"valeur":"revenu","libelle":"Gagner de l''argent"},{"valeur":"qualite_de_vie","libelle":"Mieux vivre, plus de liberté"},{"valeur":"transmission","libelle":"Transmettre quelque chose à mes enfants"},{"valeur":"securite","libelle":"Avoir une sécurité, manger à ma faim"},{"valeur":"interet_personnel","libelle":"Parce que ça me passionne"}]'::jsonb, '{"cible":"profil","champ":"finalites"}'::jsonb, NULL, NULL, true, 'ce que tu attends du projet', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('terrain_objectif', 'idee', 4, 'objectif', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, 'ton objectif principal', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('competence_technique', 'idee', 5, NULL, 'Connais-tu déjà ce métier ?', NULL, 'choix', NULL, '[{"valeur":"aucune","libelle":"Pas du tout"},{"valeur":"debutant","libelle":"Un peu, je débute"},{"valeur":"moyen","libelle":"Oui, j''ai déjà pratiqué"},{"valeur":"solide","libelle":"Oui, c''est mon métier depuis des années"}]'::jsonb, '{"cible":"profil","champ":"competenceTechnique"}'::jsonb, NULL, 'savoir_faire', true, 'ton niveau dans le métier', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('competence_gestion', 'idee', 6, NULL, 'Sais-tu tenir tes comptes, c''est-à-dire noter ce que tu dépenses et ce que tu gagnes ?', NULL, 'choix', NULL, '[{"valeur":"aucune","libelle":"Non, jamais"},{"valeur":"debutant","libelle":"Un peu, de façon irrégulière"},{"valeur":"moyen","libelle":"Oui, je note régulièrement"},{"valeur":"solide","libelle":"Oui, je tiens des comptes précis"}]'::jsonb, '{"cible":"profil","champ":"competenceGestion"}'::jsonb, NULL, 'savoir_faire', false, 'ton habitude des comptes', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('competence_vente', 'idee', 7, NULL, 'As-tu déjà vendu des produits, au marché ou à des clients ?', NULL, 'choix', NULL, '[{"valeur":"aucune","libelle":"Non, jamais"},{"valeur":"debutant","libelle":"Un peu, de temps en temps"},{"valeur":"moyen","libelle":"Oui, régulièrement"},{"valeur":"solide","libelle":"Oui, c''est ce que je fais le mieux"}]'::jsonb, '{"cible":"profil","champ":"competenceVente"}'::jsonb, NULL, 'savoir_faire', false, 'ton expérience de la vente', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
('temps_engagement', 'idee', 8, NULL, 'Vas-tu t''y consacrer à plein temps ou à temps partiel ?', NULL, 'choix', NULL, '[{"valeur":"plein","libelle":"À plein temps"},{"valeur":"partiel","libelle":"À temps partiel, j''ai une autre activité"}]'::jsonb, '{"cible":"profil","champ":"tempsEngagement"}'::jsonb, NULL, 'travail', true, 'le temps que tu y consacres', 'brouillon_ia', 'Cultiso, entretien de cadrage (consultation en six temps) ; rédigé par Cultiso, à faire relire par un agroéconomiste.'),
